function branchForm() { return `${breadcrumb([['dashboard', 'Administración'], ['branches', 'Sucursales'], ['branch-form', 'Nueva sucursal']])}${pageHeader('Nueva sucursal', 'Registra una sede y asígnala a una empresa.')}<div class="panel form-layout"><form id="branch-form"><div class="form-section"><h3>Información general</h3><div class="form-grid"><div class="field"><label>Empresa</label><select name="companyId" required>${state.companies.map(company => `<option value="${company.id}">${escapeHtml(company.name)}</option>`).join('')}</select></div><div class="field"><label>Nombre</label><input name="name" required placeholder="Ej. Central"></div><div class="field"><label>Código</label><input name="code" required placeholder="Ej. CEN-001"></div><div class="field"><label>Encargado</label><input name="managerUserId" placeholder="ID del usuario encargado"></div></div></div><div class="form-section"><h3>Contacto</h3><div class="form-grid"><div class="field"><label>Email</label><input name="email" type="email"></div><div class="field"><label>Teléfono</label><input name="phone"></div><div class="field full"><label>Dirección</label><textarea name="address"></textarea></div></div></div><div class="form-actions"><button type="button" class="secondary" data-action="cancel-form">Cancelar</button><button type="submit" class="primary">Guardar sucursal</button></div></form></div>`; }
function branchDetail(id) { const branch = state.branches.find(item => item.id === id); if (!branch) return '<div class="empty">Sucursal no encontrada.</div>'; return `${breadcrumb([['dashboard', 'Administración'], ['branches', 'Sucursales'], ['branches', branch.name]])}<div class="detail-head"><div><h1>${escapeHtml(branch.name)}</h1><p class="subtitle">${escapeHtml(branch.code)} · ${escapeHtml(branch.company)} · ${badge(branch.status)}</p></div></div><div class="grid-2"><div class="panel"><div class="panel-head"><h2>Información general</h2></div><div class="panel-body"><p><strong>Empresa</strong><br>${escapeHtml(branch.company)}</p><p><strong>Usuarios asignados</strong><br>${branch.users}</p><p><strong>Encargado</strong><br>${escapeHtml(branch.manager)}</p></div></div><div class="panel"><div class="panel-head"><h2>Estado</h2></div><div class="panel-body">${badge(branch.status)}</div></div></div>`; }
