const navOrder = ['dashboard', 'inventory', 'products', 'stock', 'movements', 'alerts', 'finance', 'companies', 'users', 'branches', 'roles', 'audit'];
nav.sort((left, right) => navOrder.indexOf(left.id) - navOrder.indexOf(right.id));

function escapeHtml(value) { return String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char])); }
function badge(status) { return `<span class="badge ${status === 'Activa' ? 'active' : 'inactive'}">${escapeHtml(status)}</span>`; }
function toast(message) { const node = document.createElement('div'); node.className = 'toast'; node.textContent = message; toastRegion.append(node); setTimeout(() => node.remove(), 3200); }
function initials(name) { return name.split(' ').map(part => part[0]).slice(0, 2).join(''); }
function displayDate(value) { return value ? new Intl.DateTimeFormat('es-DO', { dateStyle: 'medium' }).format(new Date(value)) : 'Nunca'; }
function runGlobalSearch() {
  const query = state.query.trim().toLowerCase();
  if (!query) return;
  if (state.users.some(user => `${user.name} ${user.email} ${user.company}`.toLowerCase().includes(query))) state.view = 'users';
  else if (state.companies.some(company => `${company.name} ${company.rnc}`.toLowerCase().includes(query))) state.view = 'companies';
  else if (state.branches.some(branch => `${branch.name} ${branch.code} ${branch.company}`.toLowerCase().includes(query))) state.view = 'branches';
  else { toast('No encontramos coincidencias.'); return; }
  render();
}
async function loadData() {
  const [companiesResponse, usersResponse, branchesResponse, rolesResponse, permissionsResponse, auditResponse, profileResponse, productsResponse, stockResponse, movementsResponse, financeResponse, financeTransactionsResponse, financeInvoicesResponse, financeContactsResponse, financeBankResponse] = await Promise.all([
    fetch(`/api/companies?page=${state.companiesPage}&pageSize=${state.companiesPageSize}`, { credentials: 'include' }), fetch('/api/users', { credentials: 'include' }), fetch('/api/branches', { credentials: 'include' }), fetch('/api/roles', { credentials: 'include' }), fetch('/api/permissions', { credentials: 'include' }), fetch(`/api/audit?search=${encodeURIComponent(state.auditSearch)}&module=${encodeURIComponent(state.auditModule)}&action=${encodeURIComponent(state.auditAction)}`, { credentials: 'include' }), fetch('/api/profile', { credentials: 'include' }), fetch('/api/inventory/products', { credentials: 'include' }), fetch('/api/inventory/stock', { credentials: 'include' }), fetch('/api/inventory/movements', { credentials: 'include' }), fetch('/api/finance/summary', { credentials: 'include' }), fetch('/api/finance/transactions', { credentials: 'include' }), fetch('/api/finance/invoices', { credentials: 'include' }), fetch('/api/finance/contacts', { credentials: 'include' }), fetch('/api/finance/bank-transactions', { credentials: 'include' })
  ]);
  const requiredResponses = [['empresas', companiesResponse], ['usuarios', usersResponse], ['sucursales', branchesResponse], ['auditoría', auditResponse], ['perfil', profileResponse], ['productos', productsResponse], ['existencias', stockResponse], ['movimientos', movementsResponse], ['finanzas', financeResponse], ['transacciones financieras', financeTransactionsResponse], ['facturas', financeInvoicesResponse], ['contactos financieros', financeContactsResponse], ['movimientos bancarios', financeBankResponse]];
  const failedResources = requiredResponses.filter(([, response]) => !response.ok).map(([name]) => name);
  if (failedResources.length) {
    throw new Error(`No fue posible cargar: ${failedResources.join(', ')}.`);
  }
  const companiesPayload = await companiesResponse.json();
  state.companiesTotal = companiesPayload.total;
  state.companies = companiesPayload.data.map(company => ({
    id: company.Id, name: escapeHtml(company.Name), rnc: escapeHtml(company.Rnc), users: company.UserCount,
    activeUsers: company.ActiveUserCount, inactiveUsers: company.InactiveUserCount,
    branches: company.BranchCount, status: company.IsActive ? 'Activa' : 'Inactiva',
    date: displayDate(company.CreatedAt), email: escapeHtml(company.ContactEmail || '')
  }));
  state.users = (await usersResponse.json()).map(user => ({
    id: user.id, name: escapeHtml(user.name), email: escapeHtml(user.email || 'Sin email'), company: escapeHtml(user.company),
    branch: escapeHtml(user.branch || 'Sin sucursal'), role: escapeHtml(user.role), status: user.IsActive ? 'Activa' : 'Inactiva',
    last: displayDate(user.LastLoginAt)
  }));
  state.branches = (await branchesResponse.json()).map(branch => ({
    id: branch.id, name: escapeHtml(branch.name), code: escapeHtml(branch.code), company: escapeHtml(branch.company),
    manager: escapeHtml(branch.managerUserId || 'Sin encargado'), users: branch.userCount,
    status: branch.IsActive ? 'Activa' : 'Inactiva'
  }));
  state.roles = rolesResponse.ok ? (await rolesResponse.json()).map(role => ({
    id: role.id, name: role.name, description: role.description || '', users: role.userCount, type: role.type
  })) : [];
  state.permissions = permissionsResponse.ok ? await permissionsResponse.json() : [];
  state.audit = (await auditResponse.json()).map(item => ({
    id: item.id, date: displayDate(item.CreatedAt), user: item.userName, action: item.action,
    module: item.module, record: item.record || item.entity || '', ip: item.ip || 'N/D'
  }));
  state.currentUser = await profileResponse.json();
  state.products = (await productsResponse.json()).map(product => ({
    id: product.id, sku: escapeHtml(product.sku), name: escapeHtml(product.name), category: escapeHtml(product.category || 'Sin categoría'),
    unit: escapeHtml(product.unit), stock: Number(product.stock), minimum: Number(product.minimum), price: Number(product.price), active: product.isActive
  }));
  state.stock = (await stockResponse.json()).map(item => ({
    id: item.id, productId: item.productId, sku: escapeHtml(item.sku), product: escapeHtml(item.product),
    unit: escapeHtml(item.unit), minimum: Number(item.minimum), quantity: Number(item.quantity), branchId: item.branchId, branch: escapeHtml(item.branch)
  }));
  state.movements = (await movementsResponse.json()).map(movement => ({
    id: movement.id, date: displayDate(movement.createdAt), type: movement.type, product: escapeHtml(movement.product),
    productId: movement.productId, quantity: Number(movement.quantity), branchId: movement.branchId, warehouse: escapeHtml(movement.branch), user: escapeHtml(movement.userName)
  }));
  const financePayload = await financeResponse.json();
  state.finance = { ...state.finance, ...Object.fromEntries(financePayload.transactions.map(item => [item.type === 'Ingreso' ? 'income' : 'expense', Number(item.total)])), transactions: await financeTransactionsResponse.json(), invoices: await financeInvoicesResponse.json(), contacts: await financeContactsResponse.json(), bank: await financeBankResponse.json() };
}
function pageHeader(title, description, action = '') { return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${description}</p></div>${action}</div>`; }
function canManageRoles() { return ['Super Admin', 'Company Admin'].includes(state.currentUser?.role); }
function currentOptions() { const rolesOption = canManageRoles() ? '<button class="option-card" data-nav="roles"><span class="option-icon">◇</span><span><strong>Roles y permisos</strong><small>Control de capacidades</small></span><b>→</b></button>' : ''; return `<div class="workspace-options"><div class="panel-head"><div><h2>Accesos rápidos</h2><p class="panel-note">Atajos para las tareas más frecuentes de tu organización.</p></div></div><div class="option-grid"><button class="option-card" data-nav="inventory"><span class="option-icon">◈</span><span><strong>Inventario</strong><small>Productos, existencias y movimientos</small></span><b>→</b></button><button class="option-card" data-nav="finance"><span class="option-icon">$</span><span><strong>Finanzas</strong><small>Compras, gastos y valor operativo</small></span><b>→</b></button><button class="option-card" data-nav="companies"><span class="option-icon">▦</span><span><strong>Empresas</strong><small>Organizaciones, estados y detalles</small></span><b>→</b></button><button class="option-card" data-nav="users"><span class="option-icon">♙</span><span><strong>Usuarios</strong><small>Accesos, roles y actividad</small></span><b>→</b></button><button class="option-card" data-nav="branches"><span class="option-icon">⌂</span><span><strong>Sucursales</strong><small>Sedes y usuarios asignados</small></span><b>→</b></button>${rolesOption}<button class="option-card" data-nav="audit"><span class="option-icon">≡</span><span><strong>Auditoría</strong><small>Actividad e investigación</small></span><b>→</b></button></div></div>`; }
function breadcrumb(items) { return `<div class="breadcrumb">${items.map((item, i) => i < items.length - 1 ? `<button data-nav="${item[0]}">${item[1]}</button> <span> / </span>` : `<strong>${item[1]}</strong>`).join('')}</div>`; }
function layout(content) {
  const user = state.currentUser || {};
  const userName = `${user.firstName || 'Usuario'} ${user.lastName || ''}`.trim();
  let navHtml = '';
  let currentGroup = undefined;
  nav.filter(item => item.id !== 'roles' || canManageRoles()).forEach(item => {
    const itemLabel = item.id === 'companies' && state.currentUser?.role === 'Super Admin' ? 'Empresas' : item.id === 'companies' ? 'Mi empresa' : item.label;
    if (item.group !== currentGroup) {
      currentGroup = item.group;
      if (item.group) navHtml += `<div class="nav-group-label">${item.group}</div>`;
      else if (navHtml) navHtml += `<div class="nav-divider"></div>`;
    }
    const isActive = state.view === item.id || (item.id === 'dashboard' && state.view === 'dashboard');
    navHtml += `<button class="nav-item ${isActive ? 'active' : ''}" data-nav="${item.id}" title="${itemLabel}">
      <span class="nav-item-icon">${item.icon}</span>
      <span class="nav-item-label">${itemLabel}</span>
      ${isActive ? '<span class="nav-item-dot"></span>' : ''}
    </button>`;
  });
  return `<div class="app-shell ${state.sidebarCollapsed ? 'sidebar-collapsed' : ''}">
    <aside class="sidebar">
      <div class="sidebar-inner">
        <div class="sidebar-head">
          <div class="brand">
            <div class="brand-mark"><svg viewBox="0 0 24 24" fill="none"><path d="M12 2L4 7v10l8 5 8-5V7L12 2z" fill="rgba(231,181,90,0.2)" stroke="#e7b55a" stroke-width="1.5"/><path d="M12 6l-4 2.5v5L12 16l4-2.5v-5L12 6z" fill="#e7b55a"/></svg></div>
            <div class="brand-text"><strong>Kinetix</strong><small>Core Administration</small></div>
          </div>
          <button class="sidebar-toggle" data-action="toggle-sidebar" title="${state.sidebarCollapsed ? 'Expandir' : 'Colapsar'}">
            <svg viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M3 5a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM3 10a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM3 15a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1z" clip-rule="evenodd"/></svg>
          </button>
        </div>
        <nav class="nav-menu">${navHtml}</nav>
        <div class="sidebar-footer">
          <div class="sidebar-footer-divider"></div>
          <button class="profile-card" data-nav="profile" title="Mi perfil">
            <div class="profile-avatar">${escapeHtml(initials(userName))}</div>
            <div class="profile-info">
              <strong>${escapeHtml(userName)}</strong>
              <small>${escapeHtml(user.role || 'Usuario')}</small>
            </div>
            <svg class="profile-chevron" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clip-rule="evenodd"/></svg>
          </button>
        </div>
      </div>
    </aside>
    <main class="main">
      <header class="topbar">
        <div class="topbar-left">
          <button class="mobile-menu-btn" data-action="toggle-sidebar" title="Abrir menú">☰</button>
          <div class="search"><span>⌕</span><input id="global-search" placeholder="Buscar en Kinetix" value="${escapeHtml(state.query)}"></div>
        </div>
        <div class="top-actions">
          <button class="icon-btn" title="Mi perfil" data-nav="profile">◯</button>
        </div>
      </header>
      <section class="content">${content}</section>
    </main>
  </div>`;
}

function dashboard() { const company = state.currentUser?.company || 'tu organización'; return `${breadcrumb([['dashboard', 'Workspace'], ['dashboard', company]])}${pageHeader(company, 'Este es el espacio de trabajo de tu organización.')}${currentOptions()}<div class="stats"><div class="stat"><span class="stat-label">Empresas activas</span><div class="stat-value">${state.companies.filter(c => c.status === 'Activa').length}</div><span class="stat-meta">En tu alcance</span></div><div class="stat"><span class="stat-label">Usuarios registrados</span><div class="stat-value">${state.users.length}</div><span class="stat-meta">En la organización</span></div><div class="stat"><span class="stat-label">Sucursales</span><div class="stat-value">${state.branches.length}</div><span class="stat-meta">En la organización</span></div><div class="stat"><span class="stat-label">Eventos registrados</span><div class="stat-value">${state.audit.length}</div><span class="stat-meta">Actividad reciente</span></div></div><div class="grid-2"><div class="panel"><div class="panel-head"><h2>Actividad reciente</h2><button class="row-action" data-nav="audit">Ver auditoría</button></div><div class="panel-body activity">${state.audit.slice(0, 4).map(item => `<div class="activity-item"><span class="activity-bullet"></span><div><p><strong>${item.user}</strong> realizó ${item.action.toLowerCase()} en <strong>${item.module}</strong></p><small>${item.date} · ${item.record}</small></div></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h2>Estado de la organización</h2><button class="row-action" data-nav="companies">Ver detalle</button></div><div class="panel-body">${state.companies.map(company => `<div style="display:flex;justify-content:space-between;align-items:center;padding:11px 0;border-bottom:1px solid #edf0f1;font-size:12px"><strong>${company.name}</strong>${badge(company.status)}</div>`).join('')}</div></div></div>`; }

function inventoryStats() { const lowStock = state.products.filter(product => product.stock <= product.minimum); const totalUnits = state.products.reduce((sum, product) => sum + product.stock, 0); return `<div class="stats inventory-stats"><div class="stat"><span class="stat-label">Productos activos</span><div class="stat-value">${state.products.length}</div><span class="stat-meta">Catálogo actual</span></div><div class="stat"><span class="stat-label">Unidades en stock</span><div class="stat-value">${totalUnits}</div><span class="stat-meta">En todos los almacenes</span></div><div class="stat"><span class="stat-label">Alertas de stock</span><div class="stat-value">${lowStock.length}</div><span class="stat-meta">Requieren atención</span></div><div class="stat"><span class="stat-label">Valor inventario</span><div class="stat-value">$${state.products.reduce((sum, product) => sum + product.stock * product.price, 0).toLocaleString('en-US', { maximumFractionDigits: 0 })}</div><span class="stat-meta">Costo estimado</span></div></div>`; }
function inventory() { const lowStock = state.products.filter(product => product.stock <= product.minimum); return `${breadcrumb([['dashboard', 'Workspace'], ['inventory', 'Inventory']])}${pageHeader('Inventory', 'Control operativo de productos, existencias y movimientos.', '<button class="primary" data-nav="movements">＋ Registrar movimiento</button>')}${inventoryStats()}<div class="grid-2"><div class="panel"><div class="panel-head"><div><h2>Existencias críticas</h2><p class="panel-note">Productos bajo el nivel mínimo</p></div><button class="row-action" data-nav="alerts">Ver alertas</button></div><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Stock</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${lowStock.map(product => `<tr><td><strong>${escapeHtml(product.name)}</strong><br><span class="panel-note">${product.id}</span></td><td>${product.stock} ${product.unit}</td><td>${product.minimum}</td><td><span class="badge inactive">Reponer</span></td></tr>`).join('') || '<tr><td colspan="4" class="empty">No hay existencias críticas.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panel-head"><div><h2>Últimos movimientos</h2><p class="panel-note">Actividad reciente del almacén</p></div><button class="row-action" data-nav="movements">Ver todos</button></div><div class="panel-body activity">${state.movements.slice(0, 4).map(movement => `<div class="activity-item"><span class="activity-bullet ${movement.type === 'Salida' ? 'movement-out' : ''}"></span><div><p><strong>${movement.type}</strong> · ${escapeHtml(movement.product)}</p><small>${movement.quantity} unidades · ${movement.warehouse} · ${movement.date}</small></div></div>`).join('')}</div></div></div>`; }
function products() { const items = state.products.filter(product => `${product.name} ${product.sku} ${product.category}`.toLowerCase().includes(state.query.toLowerCase())); return `${breadcrumb([['inventory', 'Inventory'], ['products', 'Productos']])}${pageHeader('Productos', 'Catálogo maestro y reglas de reposición.', '<button class="primary" data-action="new-product">＋ Nuevo producto</button>')}<div class="panel"><div class="table-toolbar"><div class="filter-row"><input id="page-search" placeholder="Buscar producto o SKU" value="${escapeHtml(state.query)}"><select><option>Todas las categorías</option><option>Operaciones</option><option>Seguridad</option><option>Mantenimiento</option></select></div><span class="panel-note">${items.length} productos</span></div><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Unidad</th><th>Stock actual</th><th>Mínimo</th><th>Costo</th><th></th></tr></thead><tbody>${items.map(product => `<tr><td><strong>${escapeHtml(product.name)}</strong><br><span class="panel-note">${escapeHtml(product.sku)}</span></td><td>${escapeHtml(product.category)}</td><td>${product.unit}</td><td>${product.stock}</td><td>${product.minimum}</td><td>$${product.price.toFixed(2)}</td><td><button class="row-action" data-action="edit-product" data-product-id="${product.id}">Editar</button><button class="row-action" data-action="toggle-product" data-product-id="${product.id}">Desactivar</button></td></tr>`).join('')}</tbody></table></div></div>`; }
function stock() { const branches = state.branches; const branchHeaders = branches.map(branch => `<th>${escapeHtml(branch.name)}</th>`).join(''); const items = state.products.filter(product => `${product.name} ${product.sku}`.toLowerCase().includes(state.query.toLowerCase())); return `${breadcrumb([['inventory', 'Inventory'], ['stock', 'Existencias']])}${pageHeader('Existencias', 'Consulta el stock disponible por producto y sucursal.', '<button class="secondary" data-nav="alerts">Ver alertas</button>')}<div class="panel"><div class="table-toolbar"><div class="filter-row"><input id="page-search" placeholder="Buscar en existencias" value="${escapeHtml(state.query)}"></div><span class="panel-note">Cantidades tomadas de la base de datos</span></div><div class="table-wrap"><table><thead><tr><th>Producto</th>${branchHeaders}<th>Total</th><th>Nivel mínimo</th><th>Estado</th></tr></thead><tbody>${items.map(product => { const locations = state.stock.filter(item => item.productId === product.id); const total = locations.reduce((sum, item) => sum + item.quantity, 0); return `<tr><td><strong>${escapeHtml(product.name)}</strong><br><span class="panel-note">${escapeHtml(product.sku)}</span></td>${branches.map(branch => `<td>${locations.find(item => item.branchId === branch.id)?.quantity || 0} ${escapeHtml(product.unit)}</td>`).join('')}<td><strong>${total}</strong></td><td>${product.minimum}</td><td><span class="badge ${total <= product.minimum ? 'inactive' : 'active'}">${total <= product.minimum ? 'Bajo' : 'Saludable'}</span></td></tr>`; }).join('') || `<tr><td colspan="${branches.length + 4}" class="empty">No hay productos para mostrar.</td></tr>`}</tbody></table></div></div>`; }
function movements() { return `${breadcrumb([['inventory', 'Inventory'], ['movements', 'Entradas / salidas']])}${pageHeader('Entradas / salidas', 'Registra cada movimiento y conserva trazabilidad del inventario.')}<div class="panel movement-form-panel"><div class="panel-head"><div><h2>Nuevo movimiento</h2><p class="panel-note">El stock se actualizará inmediatamente en la base de datos.</p></div><div class="segmented"><button class="${state.movementType === 'Entrada' ? 'active' : ''}" data-movement-type="Entrada">Entrada</button><button class="${state.movementType === 'Salida' ? 'active' : ''}" data-movement-type="Salida">Salida</button></div></div><form id="movement-form" class="movement-form"><div class="field"><label>Producto</label><select name="productId" required>${state.products.map(product => `<option value="${product.id}">${escapeHtml(product.name)} · ${product.stock} disponibles</option>`).join('')}</select></div><div class="field"><label>Cantidad</label><input name="quantity" type="number" min="1" required placeholder="0"></div><div class="field"><label>Almacén</label><select name="branchId" required>${state.branches.map(branch => `<option value="${branch.id}">${escapeHtml(branch.name)}</option>`).join('')}</select></div><button class="primary" type="submit">Registrar ${state.movementType.toLowerCase()}</button></form></div><div class="panel"><div class="panel-head"><h2>Historial de movimientos</h2><span class="panel-note">${state.movements.length} registros</span></div><div class="table-wrap"><table><thead><tr><th>Referencia</th><th>Fecha</th><th>Tipo</th><th>Producto</th><th>Cantidad</th><th>Almacén</th><th>Origen</th></tr></thead><tbody>${state.movements.map(movement => `<tr><td><strong>${movement.id}</strong></td><td>${movement.date}</td><td><span class="badge ${movement.type === 'Entrada' ? 'active' : 'pending'}">${movement.type}</span></td><td>${escapeHtml(movement.product)}</td><td>${movement.quantity}</td><td>${movement.warehouse}</td><td>${movement.user}</td></tr>`).join('')}</tbody></table></div></div>`; }
function alerts() { const alertsList = state.products.filter(product => product.stock <= product.minimum); return `${breadcrumb([['inventory', 'Inventory'], ['alerts', 'Alertas']])}${pageHeader('Alertas', 'Prioriza reposiciones antes de que afecten la operación.')}<div class="alert-list">${alertsList.map(product => `<div class="alert-item"><div class="alert-icon">!</div><div><strong>${escapeHtml(product.name)}</strong><p>Quedan ${product.stock} ${product.unit}; el mínimo configurado es ${product.minimum}.</p></div><button class="secondary" data-nav="movements">Reponer</button></div>`).join('') || '<div class="panel empty">Todo el inventario está dentro de los niveles esperados.</div>'}</div>`; }
function finance() { const inventoryValue = state.products.reduce((sum, product) => sum + product.stock * product.price, 0); const income = state.finance.income || 0; const expense = state.finance.expense || 0; return `${breadcrumb([['dashboard', 'Workspace'], ['finance', 'Finance']])}${pageHeader('Kinetix Finance', 'Controla ingresos, gastos, facturas y pagos de tu organización.', '<button class="primary" data-action="new-expense">＋ Registrar gasto</button>')}<div class="stats finance-stats"><div class="stat"><span class="stat-label">Valor del inventario</span><div class="stat-value">$${inventoryValue.toLocaleString('en-US', { maximumFractionDigits: 0 })}</div><span class="stat-meta">Desde Inventory</span></div><div class="stat"><span class="stat-label">Ingresos del mes</span><div class="stat-value">$${income.toLocaleString('en-US', { maximumFractionDigits: 0 })}</div><span class="stat-meta">Transacciones aprobadas</span></div><div class="stat"><span class="stat-label">Gastos del mes</span><div class="stat-value">$${expense.toLocaleString('en-US', { maximumFractionDigits: 0 })}</div><span class="stat-meta">Transacciones registradas</span></div><div class="stat"><span class="stat-label">Resultado del mes</span><div class="stat-value">$${(income - expense).toLocaleString('en-US', { maximumFractionDigits: 0 })}</div><span class="stat-meta">Ingresos menos gastos</span></div></div><div class="grid-2"><div class="panel"><div class="panel-head"><h2>Últimas transacciones</h2><span class="panel-note">${state.finance.transactions.length} registros</span></div><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Categoría</th><th>Monto</th><th>Estado</th></tr></thead><tbody>${state.finance.transactions.slice(0, 6).map(item => `<tr><td>${escapeHtml(item.type)}</td><td>${escapeHtml(item.category)}</td><td>$${Number(item.amount).toFixed(2)}</td><td><span class="badge ${item.status === 'Revertida' ? 'inactive' : 'pending'}">${escapeHtml(item.status)}</span></td></tr>`).join('') || '<tr><td colspan="4" class="empty">No hay transacciones financieras.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panel-head"><h2>Facturas y contactos</h2><span class="panel-note">${state.finance.invoices.length} facturas · ${state.finance.contacts.length} contactos</span></div><div class="panel-body"><p class="subtitle">Clientes, proveedores y documentos quedan preparados para cuentas por cobrar y pagar.</p><button class="row-action" data-action="new-contact">＋ Agregar cliente o proveedor</button></div></div></div>`; }
function financeWorkspace() { const tabs = [['overview', 'Resumen'], ['transactions', 'Transacciones'], ['invoices', 'Facturas'], ['contacts', 'Clientes y proveedores'], ['bank', 'Conciliación bancaria']]; let body = ''; if (state.financeTab === 'transactions') body = `<div class="panel"><div class="panel-head"><h2>Transacciones</h2><button class="primary" data-action="new-expense">＋ Nueva transacción</button></div><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Categoría</th><th>Monto</th><th>Vencimiento</th><th>Estado</th><th></th></tr></thead><tbody>${state.finance.transactions.map(item => `<tr><td>${escapeHtml(item.type)}</td><td>${escapeHtml(item.category)}</td><td>$${Number(item.amount).toFixed(2)}</td><td>${displayDate(item.dueDate)}</td><td><span class="badge pending">${escapeHtml(item.status)}</span></td><td>${item.status === 'Pendiente' ? `<button class="row-action" data-action="finance-status" data-finance-id="${item.id}" data-finance-status="Aprobada">Aprobar</button>` : ''}${item.status !== 'Revertida' ? `<button class="row-action" data-action="finance-status" data-finance-id="${item.id}" data-finance-status="Revertida">Revertir</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No hay transacciones.</td></tr>'}</tbody></table></div></div>`; if (state.financeTab === 'invoices') body = `<div class="panel"><div class="panel-head"><h2>Facturas</h2><button class="primary" data-action="new-invoice">＋ Nueva factura</button></div><div class="table-wrap"><table><thead><tr><th>Número</th><th>Tipo</th><th>Contacto</th><th>Total</th><th>Vencimiento</th><th>Estado</th><th></th></tr></thead><tbody>${state.finance.invoices.map(item => `<tr><td><strong>${escapeHtml(item.number)}</strong></td><td>${escapeHtml(item.type)}</td><td>${escapeHtml(item.contact || 'Sin contacto')}</td><td>$${Number(item.total).toFixed(2)}</td><td>${displayDate(item.dueDate)}</td><td><span class="badge pending">${escapeHtml(item.status)}</span></td><td><button class="row-action" data-action="new-payment" data-invoice-id="${item.id}">Registrar pago</button></td></tr>`).join('') || '<tr><td colspan="7" class="empty">No hay facturas.</td></tr>'}</tbody></table></div></div>`; if (state.financeTab === 'contacts') body = `<div class="panel"><div class="panel-head"><h2>Clientes y proveedores</h2><button class="primary" data-action="new-contact">＋ Nuevo contacto</button></div><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Nombre</th><th>Identificación</th><th>Email</th><th>Teléfono</th></tr></thead><tbody>${state.finance.contacts.map(item => `<tr><td>${escapeHtml(item.type)}</td><td><strong>${escapeHtml(item.name)}</strong></td><td>${escapeHtml(item.taxId || 'N/D')}</td><td>${escapeHtml(item.email || 'N/D')}</td><td>${escapeHtml(item.phone || 'N/D')}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">No hay contactos.</td></tr>'}</tbody></table></div></div>`; if (state.financeTab === 'bank') body = `<div class="panel"><div class="panel-head"><h2>Conciliación bancaria</h2><button class="primary" data-action="new-bank">＋ Registrar movimiento</button></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Descripción</th><th>Referencia</th><th>Monto</th><th>Estado</th><th></th></tr></thead><tbody>${state.finance.bank.map(item => `<tr><td>${displayDate(item.transactionDate)}</td><td>${escapeHtml(item.description)}</td><td>${escapeHtml(item.reference || 'N/D')}</td><td>$${Number(item.amount).toFixed(2)}</td><td><span class="badge ${item.status === 'Conciliada' ? 'active' : 'pending'}">${escapeHtml(item.status)}</span></td><td>${item.status !== 'Conciliada' ? `<button class="row-action" data-action="reconcile-bank" data-bank-id="${item.id}">Conciliar</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No hay movimientos bancarios.</td></tr>'}</tbody></table></div></div>`; return `<div class="finance-workspace"><div class="detail-tabs finance-tabs">${tabs.map(([id, label]) => `<button class="${state.financeTab === id ? 'active' : ''}" data-finance-tab="${id}">${label}</button>`).join('')}</div>${body}</div>`; }

function myCompany() { const company = state.companies[0]; if (!company) return `${breadcrumb([['dashboard', 'Inicio'], ['companies', 'Mi empresa']])}${pageHeader('Mi empresa', 'No hay una organización disponible para tu usuario.')}<div class="panel empty">No se encontró el perfil de la empresa.</div>`; return `${breadcrumb([['dashboard', 'Inicio'], ['companies', 'Mi empresa']])}${pageHeader('Mi empresa', 'Consulta la información de la organización a la que perteneces.')}<div class="detail-head"><div><h1>${escapeHtml(company.name)}</h1><p class="subtitle">RNC ${escapeHtml(company.rnc)} · ${badge(company.status)}</p></div></div><div class="detail-summary"><div><strong>${company.users}</strong><span>Usuarios</span></div><div><strong>${company.branches}</strong><span>Sucursales</span></div><div><strong>${company.activeUsers}</strong><span>Usuarios activos</span></div><div><strong>${company.inactiveUsers}</strong><span>Usuarios inactivos</span></div></div><div class="grid-2"><div class="panel"><div class="panel-head"><h2>Información de la empresa</h2></div><div class="panel-body"><div class="form-grid"><div><span class="panel-note">Nombre</span><p>${escapeHtml(company.name)}</p></div><div><span class="panel-note">RNC</span><p>${escapeHtml(company.rnc)}</p></div><div><span class="panel-note">Email de contacto</span><p>${escapeHtml(company.email || 'Sin email')}</p></div><div><span class="panel-note">Estado</span><p>${badge(company.status)}</p></div></div></div></div><div class="panel"><div class="panel-head"><h2>Tu espacio</h2></div><div class="panel-body"><p class="subtitle">La información que ves en Kinetix pertenece únicamente a esta organización.</p><button class="row-action" data-nav="profile">Ver mi perfil →</button></div></div></div>`; }

function companies() { const items = state.companies.filter(c => `${c.name} ${c.rnc}`.toLowerCase().includes(state.query.toLowerCase())); const start = state.companiesTotal ? ((state.companiesPage - 1) * state.companiesPageSize) + 1 : 0; const end = start ? Math.min(start + items.length - 1, state.companiesTotal) : 0; const pageCount = Math.max(Math.ceil(state.companiesTotal / state.companiesPageSize), 1); return `${breadcrumb([['dashboard', 'Administración'], ['companies', 'Empresas']])}${pageHeader('Empresas', 'Administra las organizaciones y su estado de acceso.', '<button class="primary" data-action="new-company">＋ Nueva empresa</button>')}<div class="panel"><div class="table-toolbar"><div class="filter-row"><input id="page-search" placeholder="Buscar por nombre o RNC" value="${escapeHtml(state.query)}"><select><option>Todos los estados</option><option>Activa</option><option>Inactiva</option></select></div><span class="panel-note">${state.companiesTotal} empresas encontradas</span></div><div class="table-wrap"><table><thead><tr><th>Empresa</th><th>RNC</th><th>Usuarios</th><th>Sucursales</th><th>Estado</th><th>Alta</th><th></th></tr></thead><tbody>${items.length ? items.map(c => `<tr><td><strong>${c.name}</strong><br><span class="panel-note">${c.email}</span></td><td>${c.rnc}</td><td>${c.users}</td><td>${c.branches}</td><td>${badge(c.status)}</td><td>${c.date}</td><td><button class="row-action" data-detail="company" data-id="${c.id}">Ver detalle</button></td></tr>`).join('') : '<tr><td colspan="7" class="empty">No encontramos empresas con esa búsqueda.</td></tr>'}</tbody></table></div><div class="pagination"><span>Mostrando ${start}-${end} de ${state.companiesTotal} registros</span><div class="pages">${Array.from({ length: pageCount }, (_, index) => `<button class="${index + 1 === state.companiesPage ? 'active' : ''}" data-page="${index + 1}">${index + 1}</button>`).join('')}</div></div></div>`; }

function users() { const items = state.users.filter(u => `${u.name} ${u.email} ${u.company}`.toLowerCase().includes(state.query.toLowerCase())); return `${breadcrumb([['dashboard', 'Administración'], ['users', 'Usuarios']])}${pageHeader('Usuarios', 'Controla identidades, roles y acceso por empresa.', '<button class="primary" data-action="new-user">＋ Nuevo usuario</button>')}<div class="panel"><div class="table-toolbar"><div class="filter-row"><input id="page-search" placeholder="Buscar nombre o email" value="${escapeHtml(state.query)}"><select><option>Todas las empresas</option><option>Grupo Altura</option><option>Norte Logística</option></select><select><option>Todos los estados</option><option>Activa</option><option>Inactiva</option></select></div><span class="panel-note">${items.length} usuarios</span></div><div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Empresa</th><th>Sucursal</th><th>Rol</th><th>Estado</th><th>Último acceso</th><th></th></tr></thead><tbody>${items.map(u => `<tr><td><strong>${u.name}</strong><br><span class="panel-note">${u.email}</span></td><td>${u.company}</td><td>${u.branch}</td><td>${u.role}</td><td>${badge(u.status)}</td><td>${u.last}</td><td><button class="row-action" data-detail="user" data-id="${u.id}">Ver detalle</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>Mostrando 1-${items.length} de ${items.length} registros</span><div class="pages"><button class="active">1</button><button>2</button><button>›</button></div></div></div>`; }

function branches() { return `${breadcrumb([['dashboard', 'Administración'], ['branches', 'Sucursales']])}${pageHeader('Sucursales', 'Consulta y organiza las sedes de tus empresas.', '<button class="primary" data-action="new-branch">＋ Nueva sucursal</button>')}<div class="panel"><div class="table-toolbar"><div class="filter-row"><input id="page-search" placeholder="Buscar sucursal o código" value="${escapeHtml(state.query)}"><select><option>Todas las empresas</option><option>Grupo Altura</option><option>Norte Logística</option></select></div><span class="panel-note">${state.branches.length} sucursales</span></div><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Código</th><th>Empresa</th><th>Encargado</th><th>Usuarios</th><th>Estado</th><th></th></tr></thead><tbody>${state.branches.filter(b => `${b.name} ${b.code}`.toLowerCase().includes(state.query.toLowerCase())).map(b => `<tr><td><strong>${b.name}</strong></td><td>${b.code}</td><td>${b.company}</td><td>${b.manager}</td><td>${b.users}</td><td>${badge(b.status)}</td><td><button class="row-action" data-detail="branch" data-id="${b.id}">Ver detalle</button></td></tr>`).join('')}</tbody></table></div></div>`; }

function roles() { return `${breadcrumb([['dashboard', 'Administración'], ['roles', 'Roles y permisos']])}${pageHeader('Roles y permisos', 'Define el alcance de cada perfil dentro de Kinetix.', '<button class="primary" data-action="new-role">＋ Nuevo rol</button>')}<div class="panel"><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Descripción</th><th>Usuarios</th><th>Tipo</th><th></th></tr></thead><tbody>${state.roles.map(r => `<tr><td><strong>${escapeHtml(r.name)}</strong></td><td>${escapeHtml(r.description)}</td><td>${r.users}</td><td>${escapeHtml(r.type)}</td><td><button class="row-action" data-action="edit-role" data-role="${escapeHtml(r.name)}" data-role-id="${r.id}">Editar permisos</button></td></tr>`).join('')}</tbody></table></div></div>`; }

function audit() { return `${breadcrumb([['dashboard', 'Administración'], ['audit', 'Auditoría']])}${pageHeader('Auditoría', 'Investiga las acciones realizadas dentro de la plataforma.')}<div class="panel"><div class="table-toolbar"><div class="filter-row"><input id="page-search" placeholder="Buscar usuario o registro" value="${escapeHtml(state.auditSearch)}"><select data-audit-filter="module"><option value="">Todos los módulos</option><option value="Usuarios">Usuarios</option><option value="Empresas">Empresas</option><option value="Acceso">Acceso</option></select><select data-audit-filter="action"><option value="">Todas las acciones</option><option value="CREATE">CREATE</option><option value="UPDATE">UPDATE</option><option value="LOGIN">LOGIN</option></select><button class="primary" data-action="refresh-audit">Buscar</button></div></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Módulo</th><th>Registro</th><th>IP</th><th></th></tr></thead><tbody>${state.audit.map(a => `<tr><td>${a.date}</td><td><strong>${escapeHtml(a.user)}</strong></td><td><span class="badge ${a.action === 'DEACTIVATE' ? 'inactive' : 'active'}">${escapeHtml(a.action)}</span></td><td>${escapeHtml(a.module)}</td><td>${escapeHtml(a.record)}</td><td>${escapeHtml(a.ip)}</td><td><button class="row-action" data-action="audit-detail" data-audit-id="${a.id}">Ver detalle</button></td></tr>`).join('')}</tbody></table></div></div>`; }

function profile() { const user = state.currentUser || {}; return `${breadcrumb([['dashboard', 'Administración'], ['profile', 'Mi perfil']])}${pageHeader('Mi perfil', 'Gestiona tus datos personales y credenciales.')}<form id="profile-form" class="panel form-layout"><div class="form-section"><h3>Información personal</h3><div class="form-grid"><div class="field"><label>Nombre</label><input name="firstName" required value="${escapeHtml(user.firstName)}"></div><div class="field"><label>Apellido</label><input name="lastName" required value="${escapeHtml(user.lastName)}"></div><div class="field"><label>Email</label><input name="email" required value="${escapeHtml(user.email)}" type="email"></div><div class="field"><label>Teléfono</label><input name="phone" value="${escapeHtml(user.phone)}"></div></div></div><div class="form-section"><h3>Acceso y organización</h3><div class="form-grid"><div class="field"><label>Empresa</label><input value="${escapeHtml(user.company)}" disabled></div><div class="field"><label>Rol</label><input value="${escapeHtml(user.role)}" disabled></div><div class="field"><label>Sucursal</label><input value="${escapeHtml(user.branch || 'Sin sucursal')}" disabled></div></div></div><div class="form-actions"><button type="button" class="secondary" data-action="change-password">Cambiar contraseña</button><button type="submit" class="primary">Guardar cambios</button></div></form>`; }

function form(type) { const isUser = type === 'user'; const title = isUser ? 'Nuevo usuario' : 'Nueva empresa'; const desc = isUser ? 'Crea una identidad y define su alcance dentro de la organización.' : 'Registra una nueva organización para administrar sus accesos.'; return `${breadcrumb([[isUser ? 'users' : 'companies', 'Administración'], [isUser ? 'users' : 'companies', isUser ? 'Usuarios' : 'Empresas'], [state.view, title]])}${pageHeader(title, desc)}<div class="panel form-layout"><form id="entity-form"><div class="form-section"><h3>${isUser ? 'Información personal' : 'Información general'}</h3><div class="form-grid">${isUser ? '<div class="field"><label>Nombre</label><input required name="firstName" placeholder="Ej. Juan"></div><div class="field"><label>Apellido</label><input required name="lastName" placeholder="Ej. Pérez"></div>' : '<div class="field"><label>Nombre de empresa</label><input required name="name" placeholder="Ej. Grupo Altura"></div><div class="field"><label>RNC</label><input required name="rnc" placeholder="1-01-00000-0"></div><div class="field full"><label>Logo</label><input type="file"><span class="helper">PNG o JPG, máximo 2 MB.</span></div>'}</div></div><div class="form-section"><h3>${isUser ? 'Contacto y organización' : 'Contacto'}</h3><div class="form-grid"><div class="field"><label>Email</label><input required type="email" name="email" placeholder="correo@empresa.com"></div><div class="field"><label>Teléfono</label><input name="phone" placeholder="+1 809 000 0000"></div>${isUser ? '<div class="field"><label>Empresa</label><select name="company"><option>Grupo Altura</option><option>Norte Logística</option></select></div><div class="field"><label>Sucursal</label><select name="branch"><option>Central</option><option>Piantini</option></select><span class="helper">Solo se muestran sucursales de la empresa.</span></div>' : '<div class="field full"><label>Dirección</label><textarea name="address" placeholder="Dirección fiscal"></textarea></div>'}</div></div><div class="form-section"><h3>${isUser ? 'Acceso' : 'Estado'}</h3><div class="form-grid">${isUser ? '<div class="field"><label>Rol</label><select name="role"><option>Employee</option><option>Manager</option><option>Company Admin</option></select></div><div class="field"><label>Contraseña temporal</label><input required type="password" name="password" placeholder="Mínimo 8 caracteres"></div>' : '<div class="field"><label>Estado</label><select name="status"><option>Activa</option><option>Inactiva</option></select></div>'}</div></div><div class="form-actions"><button type="button" class="secondary" data-action="cancel-form">Cancelar</button><button type="submit" class="primary">Guardar ${isUser ? 'usuario' : 'empresa'}</button></div></form></div>`; }

function companyDetail(id) { const c = state.companies.find(x => x.id === id); return `${breadcrumb([['dashboard', 'Administración'], ['companies', 'Empresas'], ['companies', c.name]])}<div class="detail-head"><div><h1>${c.name}</h1><p class="subtitle">RNC ${c.rnc} · ${badge(c.status)}</p></div><div class="inline-actions"><button class="secondary" data-action="edit-company">Editar</button><button class="${c.status === 'Activa' ? 'danger' : 'primary'}" data-action="toggle-company">${c.status === 'Activa' ? 'Desactivar' : 'Activar'}</button></div></div><div class="detail-summary"><div><strong>${c.users}</strong><span>Usuarios totales</span></div><div><strong>${c.branches}</strong><span>Sucursales</span></div><div><strong>${c.users - 3}</strong><span>Usuarios activos</span></div><div><strong>3</strong><span>Usuarios inactivos</span></div></div><div class="detail-tabs">${['Información', 'Usuarios', 'Sucursales', 'Auditoría'].map(t => `<button class="${state.tab === t ? 'active' : ''}" data-tab="${t}">${t}</button>`).join('')}</div><div class="panel"><div class="panel-body">${state.tab === 'Información' ? `<h2>Información general</h2><div class="form-grid" style="margin-top:18px"><div><span class="panel-note">Email de contacto</span><p>${c.email}</p></div><div><span class="panel-note">Fecha de creación</span><p>${c.date}</p></div><div><span class="panel-note">Estado de cuenta</span><p>${badge(c.status)}</p></div></div>` : `<h2>${state.tab}</h2><p class="subtitle" style="margin-top:10px">Contenido cargado bajo demanda para ${c.name}.</p></div>`}</div>`; }

function userDetail(id) { const u = state.users.find(x => x.id === id); return `${breadcrumb([['dashboard', 'Administración'], ['users', 'Usuarios'], ['users', u.name]])}<div class="detail-head"><div><h1>${u.name}</h1><p class="subtitle">${u.email} · ${badge(u.status)}</p></div><div class="inline-actions"><button class="secondary" data-action="edit-user">Editar</button><button class="secondary" data-action="change-password">Cambiar contraseña</button><button class="${u.status === 'Activa' ? 'danger' : 'primary'}" data-action="toggle-user">${u.status === 'Activa' ? 'Desactivar' : 'Activar'}</button></div></div><div class="grid-2"><div class="panel"><div class="panel-head"><h2>Datos de acceso</h2></div><div class="panel-body"><div class="form-grid"><div><span class="panel-note">Empresa</span><p>${u.company}</p></div><div><span class="panel-note">Sucursal</span><p>${u.branch}</p></div><div><span class="panel-note">Rol</span><p>${u.role}</p></div><div><span class="panel-note">Último acceso</span><p>${u.last}</p></div></div></div></div><div class="panel"><div class="panel-head"><h2>Actividad reciente</h2></div><div class="panel-body activity">${state.audit.filter(a => a.user === u.name).map(a => `<div class="activity-item"><span class="activity-bullet"></span><div><p>${a.action} en ${a.module}</p><small>${a.date}</small></div></div>`).join('') || '<p class="panel-note">Sin actividad reciente.</p>'}</div></div></div>`; }

function syncCompanySummary() { if (state.view !== 'company-detail') return; const company = state.companies.find(item => item.id === state.detail); const values = document.querySelectorAll('.detail-summary strong'); if (!company || values.length < 4) return; values[2].textContent = company.activeUsers ?? 0; values[3].textContent = company.inactiveUsers ?? 0; }
async function saveEntityForm(formElement) {
  const data = Object.fromEntries(new FormData(formElement));
  const endpoint = state.view === 'company-form' ? '/api/companies' : '/api/users';
  const response = await fetch(endpoint, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
  const result = await response.json();
  if (!response.ok) throw new Error(result.message || 'No fue posible guardar la información.');
  await loadData();
  state.view = state.view === 'company-form' ? 'companies' : 'users';
  state.query = '';
  toast(state.view === 'companies' ? 'Empresa creada correctamente.' : 'Usuario creado correctamente.');
  render();
}
async function saveBranchForm(formElement) {
  const response = await fetch('/api/branches', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(new FormData(formElement))) });
  const result = await response.json();
  if (!response.ok) throw new Error(result.message || 'No fue posible guardar la sucursal.');
  await loadData();
  state.view = 'branches';
  toast('Sucursal creada correctamente.');
  render();
}
function render() { if (!state.loggedIn) { app.innerHTML = login(); bind(); return; } if (state.view === 'roles' && !canManageRoles()) state.view = 'dashboard'; let content = state.view === 'dashboard' ? dashboard() : state.view === 'inventory' ? inventory() : state.view === 'products' ? products() : state.view === 'stock' ? stock() : state.view === 'movements' ? movements() : state.view === 'alerts' ? alerts() : state.view === 'finance' ? finance() + financeWorkspace() : state.view === 'companies' ? (state.currentUser?.role === 'Super Admin' ? companies() : myCompany()) : state.view === 'users' ? users() : state.view === 'branches' ? branches() : state.view === 'roles' ? roles() : state.view === 'audit' ? audit() : state.view === 'profile' ? profile() : state.view === 'company-form' ? form('company') : state.view === 'user-form' ? form('user') : state.view === 'branch-form' ? branchForm() : state.view === 'company-detail' ? companyDetail(state.detail) : state.view === 'user-detail' ? userDetail(state.detail) : state.view === 'branch-detail' ? branchDetail(state.detail) : dashboard(); app.innerHTML = layout(content); bind(); syncCompanySummary(); }
function login() { return `<div class="login-page"><div class="login-aside"><div class="brand"><div class="brand-mark">K</div><div><strong>Kinetix</strong><small>Core administration</small></div></div><div class="login-message"><span class="eyebrow">OPERACIONES SIN FRICCIÓN</span><h1>El pulso de tu empresa, en un solo lugar.</h1><p>Gestiona personas, permisos y sucursales con la claridad que exige el trabajo diario.</p></div><small class="login-legal">Kinetix Core · Plataforma de administración empresarial</small></div><div class="login-form"><div class="login-box"><span class="eyebrow">BIENVENIDO DE VUELTA</span><h2>Iniciar sesión</h2><p>Accede a tu espacio de trabajo seguro.</p><form id="login-form"><div class="field"><label>Email</label><input name="email" type="email" required value="" placeholder="tu@email.com"></div><div class="field"><label>Contraseña</label><input name="password" type="password" required value="" placeholder="Tu contraseña"></div><div class="login-options"><label class="check"><input type="checkbox" checked> Recordarme</label><button type="button" class="row-action">¿Olvidaste tu contraseña?</button></div><button class="primary login-submit">Iniciar sesión <span>→</span></button></form></div></div></div>`; }

function bind() {
  document.querySelectorAll('[data-nav]').forEach(button => button.addEventListener('click', () => { state.view = button.dataset.nav; state.query = ''; state.detail = null; render(); }));
  document.querySelectorAll('[data-detail]').forEach(button => button.addEventListener('click', () => { state.detail = button.dataset.detail === 'user' ? button.dataset.id : Number(button.dataset.id); state.view = `${button.dataset.detail}-detail`; state.tab = 'Información'; render(); }));
  document.querySelectorAll('[data-tab]').forEach(button => button.addEventListener('click', () => { state.tab = button.dataset.tab; render(); }));
  document.querySelectorAll('[data-page]').forEach(button => button.addEventListener('click', async () => { state.companiesPage = Number(button.dataset.page); try { await loadData(); render(); } catch (error) { toast(error.message); } }));
  const search = document.querySelector('#global-search'); if (search) { search.addEventListener('input', event => { state.query = event.target.value; }); search.addEventListener('keydown', event => { if (event.key === 'Enter') { event.preventDefault(); runGlobalSearch(); } }); }
  document.querySelectorAll('[data-audit-filter]').forEach(select => select.addEventListener('change', async event => { if (event.target.dataset.auditFilter === 'module') state.auditModule = event.target.value; if (event.target.dataset.auditFilter === 'action') state.auditAction = event.target.value; await loadData(); render(); }));
  document.querySelectorAll('[data-movement-type]').forEach(button => button.addEventListener('click', () => { state.movementType = button.dataset.movementType; render(); }));
  document.querySelectorAll('[data-finance-tab]').forEach(button => button.addEventListener('click', () => { state.financeTab = button.dataset.financeTab; render(); }));
  const movementForm = document.querySelector('#movement-form'); if (movementForm) movementForm.addEventListener('submit', async event => { event.preventDefault(); const data = Object.fromEntries(new FormData(movementForm)); const response = await fetch('/api/inventory/movements', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...data, type: state.movementType, productId: Number(data.productId), branchId: Number(data.branchId), quantity: Number(data.quantity) }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible registrar el movimiento.'); await loadData(); toast(`Movimiento de ${state.movementType.toLowerCase()} registrado.`); render(); });
  const pageSearch = document.querySelector('#page-search'); if (pageSearch) { pageSearch.addEventListener('input', event => { if (state.view === 'audit') state.auditSearch = event.target.value; else state.query = event.target.value; render(); const updatedSearch = document.querySelector('#page-search'); if (updatedSearch) { updatedSearch.focus(); updatedSearch.setSelectionRange(event.target.value.length, event.target.value.length); } }); pageSearch.addEventListener('keydown', async event => { if (event.key === 'Enter' && state.view === 'audit') { event.preventDefault(); await loadData(); render(); } }); }
  document.querySelectorAll('[data-action]').forEach(button => button.addEventListener('click', () => handleAction(button.dataset.action, button)));
  const loginForm = document.querySelector('#login-form'); if (loginForm) loginForm.addEventListener('submit', async event => { event.preventDefault(); try { const response = await fetch('/api/auth/login', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(new FormData(loginForm))) }); const result = await response.json(); if (!response.ok) throw new Error(result.message || 'No fue posible iniciar sesión.'); await loadData(); state.loggedIn = true; toast('Sesión iniciada correctamente.'); render(); } catch (error) { toast(error.message); } });
  const entityForm = document.querySelector('#entity-form'); if (entityForm) entityForm.addEventListener('submit', async event => { event.preventDefault(); try { await saveEntityForm(entityForm); } catch (error) { toast(error.message); } });
  const branchFormElement = document.querySelector('#branch-form'); if (branchFormElement) branchFormElement.addEventListener('submit', async event => { event.preventDefault(); try { await saveBranchForm(branchFormElement); } catch (error) { toast(error.message); } });
}

document.addEventListener('submit', async event => {
  if (event.target.id !== 'profile-form') return;
  event.preventDefault();
  const data = Object.fromEntries(new FormData(event.target));
  try {
    const response = await fetch('/api/profile', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
    const result = await response.json();
    if (!response.ok) throw new Error(result.message || 'No fue posible guardar el perfil.');
    state.currentUser = { ...state.currentUser, ...result };
    toast('Los cambios del perfil se guardaron correctamente.');
    render();
  } catch (error) {
    toast(error.message);
  }
});

async function handleAction(action, button) {
  if (action === 'toggle-sidebar') { state.sidebarCollapsed = !state.sidebarCollapsed; render(); }
  if (action === 'new-company') { state.view = 'company-form'; render(); }
  if (action === 'new-user') { state.view = 'user-form'; render(); }
  if (action === 'new-branch') { state.view = 'branch-form'; render(); }
  if (action === 'new-product') showModal('Nuevo producto', '<div class="form-grid"><div class="field"><label>SKU</label><input class="product-sku" required placeholder="SKU-0001"></div><div class="field"><label>Nombre</label><input class="product-name" required placeholder="Nombre del producto"></div><div class="field"><label>Categoría</label><input class="product-category" placeholder="Categoría"></div><div class="field"><label>Unidad</label><input class="product-unit" value="und." required></div><div class="field"><label>Stock mínimo</label><input class="product-minimum" type="number" min="0" step="0.001" value="0" required></div><div class="field"><label>Costo unitario</label><input class="product-price" type="number" min="0" step="0.0001" value="0" required></div></div>', 'Crear producto', async modal => { const response = await fetch('/api/inventory/products', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sku: modal.querySelector('.product-sku').value, name: modal.querySelector('.product-name').value, category: modal.querySelector('.product-category').value, unit: modal.querySelector('.product-unit').value, minimum: Number(modal.querySelector('.product-minimum').value), price: Number(modal.querySelector('.product-price').value) }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible crear el producto.'); await loadData(); toast('Producto creado correctamente.'); render(); });
  if (action === 'edit-product') { const product = state.products.find(item => String(item.id) === button.dataset.productId); if (!product) return toast('El producto ya no está disponible.'); const body = `<div class="form-grid"><div class="field"><label>SKU</label><input class="product-sku" value="${escapeHtml(product.sku)}" required></div><div class="field"><label>Nombre</label><input class="product-name" value="${escapeHtml(product.name)}" required></div><div class="field"><label>Categoría</label><input class="product-category" value="${escapeHtml(product.category)}"></div><div class="field"><label>Unidad</label><input class="product-unit" value="${escapeHtml(product.unit)}" required></div><div class="field"><label>Stock mínimo</label><input class="product-minimum" type="number" min="0" step="0.001" value="${product.minimum}" required></div><div class="field"><label>Costo unitario</label><input class="product-price" type="number" min="0" step="0.0001" value="${product.price}" required></div></div>`; showModal('Editar producto', body, 'Guardar cambios', async modal => { const response = await fetch(`/api/inventory/products/${product.id}`, { method: 'PUT', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sku: modal.querySelector('.product-sku').value, name: modal.querySelector('.product-name').value, category: modal.querySelector('.product-category').value, unit: modal.querySelector('.product-unit').value, minimum: Number(modal.querySelector('.product-minimum').value), price: Number(modal.querySelector('.product-price').value) }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible actualizar el producto.'); await loadData(); toast('Producto actualizado correctamente.'); render(); }); }
  if (action === 'toggle-product') { const product = state.products.find(item => String(item.id) === button.dataset.productId); if (!product) return toast('El producto ya no está disponible.'); showModal('Desactivar producto', 'El producto dejará de aparecer en el catálogo operativo, pero conservará su historial.', 'Desactivar', async () => { const response = await fetch(`/api/inventory/products/${product.id}/status`, { method: 'PATCH', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ isActive: false }) }); if (!response.ok) return toast('No fue posible desactivar el producto.'); await loadData(); toast('Producto desactivado.'); render(); }); }
  if (action === 'refresh-audit') { loadData().then(render).catch(error => toast(error.message)); }
  if (action === 'new-role') showRoleModal('Nuevo rol');
  if (action === 'new-expense') showModal('Registrar gasto', '<div class="form-grid"><div class="field"><label>Categoría</label><input class="finance-category" required placeholder="Ej. Servicios"></div><div class="field"><label>Monto</label><input class="finance-amount" type="number" min="0.01" step="0.01" required placeholder="0.00"></div><div class="field full"><label>Descripción</label><textarea class="finance-description" placeholder="Detalle del gasto"></textarea></div></div>', 'Guardar gasto', async modal => { const response = await fetch('/api/finance/transactions', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ type: 'Gasto', category: modal.querySelector('.finance-category').value, amount: Number(modal.querySelector('.finance-amount').value), description: modal.querySelector('.finance-description').value }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible registrar el gasto.'); await loadData(); toast('Gasto registrado correctamente.'); render(); });
  if (action === 'new-contact') showModal('Nuevo cliente o proveedor', '<div class="form-grid"><div class="field"><label>Tipo</label><select class="finance-contact-type"><option>Cliente</option><option>Proveedor</option></select></div><div class="field"><label>Nombre</label><input class="finance-contact-name" required placeholder="Nombre comercial"></div><div class="field"><label>Identificación fiscal</label><input class="finance-contact-tax-id" placeholder="RNC / RFC / NIT"></div><div class="field"><label>Email</label><input class="finance-contact-email" type="email"></div><div class="field"><label>Teléfono</label><input class="finance-contact-phone"></div></div>', 'Guardar contacto', async modal => { const response = await fetch('/api/finance/contacts', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ type: modal.querySelector('.finance-contact-type').value, name: modal.querySelector('.finance-contact-name').value, taxId: modal.querySelector('.finance-contact-tax-id').value, email: modal.querySelector('.finance-contact-email').value, phone: modal.querySelector('.finance-contact-phone').value }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible guardar el contacto.'); await loadData(); toast('Contacto guardado correctamente.'); render(); });
  if (action === 'finance-status') { const response = await fetch(`/api/finance/transactions/${button.dataset.financeId}/status`, { method: 'PATCH', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: button.dataset.financeStatus }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible actualizar la transacción.'); await loadData(); render(); }
  if (action === 'new-invoice') { const contactOptions = state.finance.contacts.map(contact => '<option value="' + contact.id + '">' + escapeHtml(contact.type) + ' · ' + escapeHtml(contact.name) + '</option>').join(''); const body = '<div class="form-grid"><div class="field"><label>Número</label><input class="invoice-number" required placeholder="F-000001"></div><div class="field"><label>Tipo</label><select class="invoice-type"><option>Venta</option><option>Compra</option></select></div><div class="field"><label>Contacto</label><select class="invoice-contact"><option value="">Sin contacto</option>' + contactOptions + '</select></div><div class="field"><label>Subtotal</label><input class="invoice-subtotal" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Impuesto %</label><input class="invoice-tax" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Vencimiento</label><input class="invoice-due-date" type="date"></div></div>'; showModal('Nueva factura', body, 'Crear factura', async modal => { const response = await fetch('/api/finance/invoices', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ number: modal.querySelector('.invoice-number').value, type: modal.querySelector('.invoice-type').value, contactId: modal.querySelector('.invoice-contact').value || null, subtotal: Number(modal.querySelector('.invoice-subtotal').value), taxRate: Number(modal.querySelector('.invoice-tax').value), dueDate: modal.querySelector('.invoice-due-date').value || null }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible crear la factura.'); await loadData(); toast('Factura creada correctamente.'); render(); }); }
  if (action === 'new-payment') showModal('Registrar pago', '<div class="form-grid"><div class="field"><label>Monto</label><input class="payment-amount" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Método</label><select class="payment-method"><option>Transferencia</option><option>Tarjeta</option><option>Efectivo</option><option>Cheque</option></select></div><div class="field full"><label>Referencia</label><input class="payment-reference"></div></div>', 'Guardar pago', async modal => { const response = await fetch('/api/finance/payments', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ invoiceId: button.dataset.invoiceId, amount: Number(modal.querySelector('.payment-amount').value), method: modal.querySelector('.payment-method').value, reference: modal.querySelector('.payment-reference').value }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible registrar el pago.'); await loadData(); toast('Pago registrado correctamente.'); render(); });
  if (action === 'new-bank') showModal('Movimiento bancario', '<div class="form-grid"><div class="field"><label>Fecha</label><input class="bank-date" type="date"></div><div class="field"><label>Monto</label><input class="bank-amount" type="number" step="0.01" required></div><div class="field full"><label>Descripción</label><input class="bank-description" required></div><div class="field full"><label>Referencia</label><input class="bank-reference"></div></div>', 'Guardar movimiento', async modal => { const response = await fetch('/api/finance/bank-transactions', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ transactionDate: modal.querySelector('.bank-date').value || null, amount: Number(modal.querySelector('.bank-amount').value), description: modal.querySelector('.bank-description').value, reference: modal.querySelector('.bank-reference').value }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible guardar el movimiento bancario.'); await loadData(); toast('Movimiento bancario guardado.'); render(); });
  if (action === 'reconcile-bank') { const response = await fetch(`/api/finance/bank-transactions/${button.dataset.bankId}/reconcile`, { method: 'POST', credentials: 'include' }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible conciliar el movimiento.'); await loadData(); render(); }
  if (action === 'edit-role') showRoleModal(button.dataset.role || 'Nuevo rol', button.dataset.roleId);
  if (action === 'cancel-form') { state.view = button.closest('#branch-form') ? 'branches' : button.closest('#entity-form') ? (state.view === 'user-form' ? 'users' : 'companies') : 'dashboard'; render(); }
  if (action === 'toggle-company') { const company = state.companies.find(c => c.id === state.detail); showModal(`${company.status === 'Activa' ? 'Desactivar' : 'Activar'} empresa`, company.status === 'Activa' ? 'Al desactivar esta empresa, sus usuarios no podrán acceder al sistema.' : 'La empresa volverá a estar disponible para sus usuarios.', company.status === 'Activa' ? 'Desactivar' : 'Activar', async () => { const response = await fetch(`/api/companies/${company.id}/status`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ isActive: company.status !== 'Activa' }) }); if (!response.ok) return toast('No fue posible actualizar la empresa.'); await loadData(); toast('Estado de empresa actualizado.'); render(); }); }
  if (action === 'toggle-user') { const user = state.users.find(u => u.id === state.detail); showModal(`${user.status === 'Activa' ? 'Desactivar' : 'Activar'} usuario`, 'El cambio se registrará en auditoría y tendrá efecto inmediato.', user.status === 'Activa' ? 'Desactivar' : 'Activar', async () => { const response = await fetch(`/api/users/${encodeURIComponent(user.id)}/status`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ isActive: user.status !== 'Activa' }) }); if (!response.ok) return toast('No fue posible actualizar el usuario.'); await loadData(); toast('Estado de usuario actualizado.'); render(); }); }
  if (action === 'edit-company') { const company = state.companies.find(item => item.id === state.detail); const body = `<div class="form-grid"><div class="field"><label>Nombre</label><input class="edit-name" value="${escapeHtml(company.name)}"></div><div class="field"><label>RNC</label><input class="edit-rnc" value="${escapeHtml(company.rnc)}"></div><div class="field full"><label>Email</label><input class="edit-email" type="email" value="${escapeHtml(company.email)}"></div></div>`; showModal('Editar empresa', body, 'Guardar cambios', async modal => { const response = await fetch(`/api/companies/${company.id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: modal.querySelector('.edit-name').value, rnc: modal.querySelector('.edit-rnc').value, email: modal.querySelector('.edit-email').value }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible actualizar la empresa.'); await loadData(); toast('Empresa actualizada correctamente.'); render(); }); }
  if (action === 'edit-user') { const user = state.users.find(item => item.id === state.detail); const body = `<div class="form-grid"><div class="field"><label>Nombre</label><input class="edit-first-name" value="${escapeHtml(user.name.split(' ')[0])}"></div><div class="field"><label>Apellido</label><input class="edit-last-name" value="${escapeHtml(user.name.split(' ').slice(1).join(' '))}"></div><div class="field full"><label>Email</label><input class="edit-email" type="email" value="${escapeHtml(user.email)}"></div></div>`; showModal('Editar usuario', body, 'Guardar cambios', async modal => { const response = await fetch(`/api/users/${encodeURIComponent(user.id)}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ firstName: modal.querySelector('.edit-first-name').value, lastName: modal.querySelector('.edit-last-name').value, email: modal.querySelector('.edit-email').value }) }); const result = await response.json(); if (!response.ok) return toast(result.message || 'No fue posible actualizar el usuario.'); await loadData(); toast('Usuario actualizado correctamente.'); render(); }); }
  if (action === 'change-password') showModal('Cambiar contraseña', '<div class="field"><label>Contraseña actual</label><input class="modal-current-password" type="password" required></div><div class="field" style="margin-top:12px"><label>Nueva contraseña</label><input class="modal-password" type="password" minlength="10" required></div>', 'Guardar contraseña', async modal => { const currentPassword = modal.querySelector('.modal-current-password').value; const newPassword = modal.querySelector('.modal-password').value; const response = await fetch('/api/auth/change-password', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ currentPassword, newPassword }) }); const result = response.status === 204 ? null : await response.json(); if (!response.ok) return toast(result?.message || 'No fue posible cambiar la contraseña.'); toast('Contraseña actualizada correctamente.'); });
  if (action === 'audit-detail') { const item = state.audit.find(entry => String(entry.id) === button.dataset.auditId); if (!item) return toast('El evento de auditoría ya no está disponible.'); showModal('Detalle de auditoría', `<div style="display:grid;gap:9px;font-size:12px"><div><span class="panel-note">Usuario</span><br><strong>${escapeHtml(item.user)}</strong></div><div><span class="panel-note">Acción y módulo</span><br>${escapeHtml(item.action)} · ${escapeHtml(item.module)}</div><div><span class="panel-note">Registro afectado</span><br>${escapeHtml(item.record)}</div><div><span class="panel-note">IP / Navegador</span><br>${escapeHtml(item.ip)} · Chrome en Windows</div></div>`, 'Cerrar'); }
  if (action === 'save') { toast('Los cambios se guardaron correctamente.'); }
}
function showModal(title, body, confirm, callback = null) { const backdrop = document.createElement('div'); backdrop.className = 'modal-backdrop'; backdrop.innerHTML = `<div class="modal"><h2>${title}</h2><div>${body}</div><div class="modal-actions"><button class="secondary modal-cancel">Cancelar</button><button class="primary modal-confirm">${confirm}</button></div></div>`; document.body.append(backdrop); backdrop.querySelector('.modal-cancel').onclick = () => backdrop.remove(); backdrop.querySelector('.modal-confirm').onclick = async () => { if (callback) await callback(backdrop); backdrop.remove(); }; backdrop.addEventListener('click', event => { if (event.target === backdrop) backdrop.remove(); }); }
function showRoleModal(roleName, roleId = null) { const grouped = state.permissions.reduce((groups, permission) => { (groups[permission.module] ||= []).push(permission); return groups; }, {}); const body = `<div class="field"><label>Nombre del rol</label><input class="role-name" value="${roleName === 'Nuevo rol' ? '' : escapeHtml(roleName)}" ${roleId ? 'disabled' : ''}></div><div class="field" style="margin-top:12px"><label>Descripción</label><textarea class="role-description" placeholder="Alcance del rol"></textarea></div><div class="permission-grid" style="margin-top:18px">${Object.entries(grouped).map(([group, permissions]) => `<div class="permission-group"><h3>${escapeHtml(group)}</h3>${permissions.map(permission => `<label class="check"><input type="checkbox" data-permission-id="${permission.id}" checked>${escapeHtml(permission.name)}</label>`).join('')}</div>`).join('')}</div>`; showModal(roleName === 'Nuevo rol' ? 'Nuevo rol' : `Permisos · ${roleName}`, body, 'Guardar cambios', async modal => { let targetRoleId = roleId; if (!targetRoleId) { const name = modal.querySelector('.role-name').value.trim(); const description = modal.querySelector('.role-description').value.trim(); const createResponse = await fetch('/api/roles', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, description }) }); const created = await createResponse.json(); if (!createResponse.ok) return toast(created.message || 'No fue posible guardar el rol.'); targetRoleId = created.id; } const permissionIds = [...modal.querySelectorAll('[data-permission-id]:checked')].map(input => Number(input.dataset.permissionId)); const permissionsResponse = await fetch(`/api/roles/${targetRoleId}/permissions`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ permissionIds }) }); if (!permissionsResponse.ok) return toast('No fue posible guardar los permisos del rol.'); await loadData(); toast(roleId ? 'Permisos actualizados correctamente.' : 'Rol creado correctamente.'); render(); }); }

async function bootstrap() {
  try {
    const response = await fetch('/api/profile', { credentials: 'include' });
    if (!response.ok) throw new Error('No active session');
    state.currentUser = await response.json();
    await loadData();
    state.loggedIn = true;
  } catch (_error) {
    state.loggedIn = false;
  }
  render();
}

bootstrap();
